#!/usr/bin/env node
/**
 * Embeds the agent prompt as a plain TypeScript string module so the `lody` CLI can
 * `import` it in both bundles it uses: esbuild (dev) and Vite (production).
 * Neither supports Vite's `?raw` query here, and the published `lody` package
 * ships only `dist/` (no access to this package's data files), so the prompt must be
 * inlined as a JS string.
 *
 * Writes:
 *   - dist-standalone/embedded-prompt.ts → `reviewPrompt` (the agent prompt markdown)
 *
 * The ~8 MB single-file viewer (`dist-standalone/standalone.html`) is NOT embedded
 * here: it is shipped via the public `lody-code-review-viewer` npm package and
 * fetched on demand by `lody review` (see that package + the CLI's review-viewer
 * resolver). Keeping it out of the bundle keeps the `lody` package small.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

function emitStringModule(outFile, exportName, sourceText) {
  const banner = '// AUTO-GENERATED by scripts/embed-standalone.mjs. Do not edit by hand.\n';
  const body = `export const ${exportName} = ${JSON.stringify(sourceText)};\n`;
  mkdirSync(path.dirname(outFile), { recursive: true });
  writeFileSync(outFile, banner + body, 'utf8');
}

const promptMarkdown = readFileSync(
  path.join(packageRoot, 'prompts/review-helper-agent.md'),
  'utf8'
);
emitStringModule(
  path.join(packageRoot, 'dist-standalone/embedded-prompt.ts'),
  'reviewPrompt',
  promptMarkdown
);

const kb = (n) => `${(n / 1024).toFixed(0)} KB`;
console.log(`Embedded review prompt (${kb(promptMarkdown.length)}).`);
